-- Skema MySQL untuk migrasi dari Supabase. Jalankan sekali di phpMyAdmin.
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'admin', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS berita (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NOT NULL, slug VARCHAR(255) NULL, isi LONGTEXT NOT NULL, foto_url VARCHAR(500) NULL, kategori VARCHAR(100) NULL, tanggal DATE NULL, views INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS guru (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(255) NOT NULL, nip VARCHAR(100) NULL, jabatan VARCHAR(255) NULL, mapel VARCHAR(255) NULL, foto_url VARCHAR(500) NULL, urutan INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS prestasi (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NOT NULL, deskripsi TEXT NULL, tingkat VARCHAR(100) NULL, tahun INT NULL, foto_url VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS banner (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NULL, subjudul TEXT NULL, foto_url VARCHAR(500) NULL, link_url VARCHAR(500) NULL, urutan INT NOT NULL DEFAULT 0, aktif TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lulusan_terbaik (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(255) NOT NULL, tahun_lulus INT NULL, jurusan VARCHAR(255) NULL, pencapaian TEXT NULL, foto_url VARCHAR(500) NULL, urutan INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kurikulum (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NOT NULL, deskripsi TEXT NULL, jenis VARCHAR(100) NULL, file_url VARCHAR(500) NULL, link_url VARCHAR(500) NULL, tahun_ajaran VARCHAR(50) NULL, urutan INT NOT NULL DEFAULT 0, aktif TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kurikulum_url (id INT PRIMARY KEY, url_kurikulum VARCHAR(500) NULL, updated_at DATETIME NULL);
INSERT IGNORE INTO kurikulum_url (id, url_kurikulum) VALUES (1, '');
CREATE TABLE IF NOT EXISTS video_profil (id INT PRIMARY KEY, url_video VARCHAR(500) NULL, updated_at DATETIME NULL);
INSERT IGNORE INTO video_profil (id, url_video) VALUES (1, '');
CREATE TABLE IF NOT EXISTS visi_misi (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, visi LONGTEXT NULL, misi LONGTEXT NULL, tujuan LONGTEXT NULL, updated_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS struktur_organisasi (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, foto_url VARCHAR(500) NULL, updated_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS laporan_keuangan (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NULL, tahun INT NULL, jenis VARCHAR(50) NULL, file_url VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
